mapper.select:
select a.* from iot_collect_data a


        and a.uid=#{entity.uid}


        and a.cid=#{entity.cid}


        and a.device_sn=#{entity.deviceSn}


        and a.collect_mode = #{entity.collectMode}


        and a.product_code=#{entity.productCode}


        and a.field_id=#{entity.fieldId}


        and a.task_id=#{entity.taskId}


        and a.status=#{entity.status}


order by a.collect_time desc


    select count(1) calc_value, field, category


    select avg(CAST(collect_value AS double)) calc_value, field, category


    select max(CAST(collect_value AS double)) calc_value, field, category


    select min(CAST(collect_value AS double)) calc_value, field, category

from (
    select collect_value, field

        ,TO_CHAR(collect_time, 'yyyy') category


        ,TO_CHAR(collect_time, 'yyyy-mm') category


        ,TO_CHAR(collect_time, 'yyyy-mm-dd') category


        ,TO_CHAR(collect_time, 'yyyy-mm-dd hh24') category

    from iot_collect_data


            and uid=#{uid}


            and product_code=#{productCode}


            and (
            field = #{field}
        )

        and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

) b
group by category,field

select * from iot_collect_data


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

select * from iot_collect_data


        and uid=#{uid}


        and product_code=#{productCode}


        and (
        field = #{field}
    )

    and cast(collect_time as bigint) between #{startTimestamp} and #{endTimestamp}

select uid,cid from (
    select distinct uid, cid, collect_time from iot_collect_data


            and uid=#{entity.uid}


            and device_sn=#{entity.deviceSn}


            and collect_mode = #{entity.collectMode}


            and product_code=#{entity.productCode}


            and device_group_id=#{entity.deviceGroupId}


            and task_id=#{entity.taskId}



                and cast(collect_time as bigint) between #{entity.startTimestamp} and #{entity.endTimestamp}


                and cast(collect_time as bigint) >= #{entity.startTimestamp}


                and #{entity.endTimestamp} >= cast(collect_time as bigint)



)
order by collect_time desc
